    /** Exact Hermite corner values for the shared wall/body field, not baked pixels. */
    private static final class ReliefLattices {
        private final long seed;
        private final Lattice[] lattices;
        private static final class Lattice {
            final int count,rows;final double px,py;final long salt;final double[] values;
            Lattice(long seed,double px,double py,long salt){this.px=px;this.py=py;this.salt=salt;
                count=Math.max(2,(int)Math.floor(2*Math.PI*450/px+.5));rows=(int)Math.floor(1500/py)+2;values=new double[count*rows];
                for(int y=0;y<rows;y++)for(int x=0;x<count;x++)values[y*count+x]=mixUnit(seed^LivingAbyssFields.mix(x)^Long.rotateLeft(LivingAbyssFields.mix(y),31)^LivingAbyssFields.mix(salt));
            }
            double at(long seed,double theta,double d){double x=LivingAbyssFields.normalize(theta)/360*count,y=d/py;long ix=(long)Math.floor(x),iy=(long)Math.floor(y);
                if(iy<0||iy+1>=rows)return noise(seed,theta,d,px,py,salt,450);
                double fx=LivingAbyssFields.smooth(x-ix),fy=LivingAbyssFields.smooth(y-iy);int x0=Math.floorMod(ix,count),x1=(x0+1)%count,y0=(int)iy*count,y1=y0+count;
                double a=values[y0+x0],b=values[y0+x1],c=values[y1+x0],e=values[y1+x1];
                return (a+(b-a)*fx)*(1-fy)+(c+(e-c)*fx)*fy;
            }
        }
        ReliefLattices(long seed){this.seed=seed;lattices=new Lattice[]{new Lattice(seed,60,60,ROCK_RELIEF+31),new Lattice(seed,34,340,ROCK_RELIEF+32),
            new Lattice(seed,90,180,ROCK_RELIEF+33),new Lattice(seed,18,144,ROCK_RELIEF+34),new Lattice(seed,6,120,ROCK_RELIEF+35)};}
        double at(double theta,double d,int index){return lattices[index].at(seed,theta,d);}
        int bytes(){int n=0;for(var a:lattices)n+=a.values.length*Double.BYTES;return n;}
    }
